import sys
data = sys.stdin.read().split()
n = int(data[0])
b = [int(x) for x in data[1:1 + n]]
a = [int(x) for x in data[1 + n:1 + 2 * n]]
best = 0
for l in range(n):
    mn = b[l]
    mx = a[l]
    for r in range(l, n):
        if b[r] < mn:
            mn = b[r]
        if a[r] > mx:
            mx = a[r]
        if mn < mx:
            break
        if r - l + 1 > best:
            best = r - l + 1
print(best)
